:root {
  --bg: #1b1f3b;
  --bg-accent: #2a2f5a;
  --card: #f7f7fb;
  --ink: #1b1f3b;
  --muted: #4a4f73;
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-pressed: #3730a3;
  --focus: #f59e0b;
  --border: #d7d9e6;
  --radius: 14px;
  --shadow: 0 18px 40px rgba(10, 12, 30, 0.35);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(circle at 20% 20%, #3b3f7a 0%, transparent 45%),
    radial-gradient(circle at 80% 80%, #2a2f5a 0%, transparent 50%),
    var(--bg);
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.card-header h1 {
  margin: 0 0 6px;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.swatches {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: #ffffff;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.swatch.is-locked {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(79, 70, 229, 0.18);
}

.swatch-color {
  flex: 0 0 64px;
  width: 64px;
  height: 64px;
  border-radius: 10px;
  border: 1px solid rgba(0, 0, 0, 0.12);
}

.swatch-info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.swatch-hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.swatch-label {
  font-size: 0.9rem;
  color: var(--muted);
}

.lock-btn {
  flex: 0 0 auto;
  min-width: 84px;
  padding: 10px 12px;
  font-size: 0.95rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--ink);
  background: #eef0f8;
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}

.lock-btn:hover {
  background: #e3e6f4;
  border-color: #b9bed6;
}

.lock-btn:active {
  transform: translateY(1px);
  background: #d8dcee;
}

.lock-btn[aria-pressed="true"] {
  color: #ffffff;
  background: var(--primary);
  border-color: var(--primary);
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.lock-btn[aria-pressed="true"]:active {
  background: var(--primary-pressed);
  border-color: var(--primary-pressed);
}

.actions {
  display: flex;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease;
}

.btn-primary {
  width: 100%;
  padding: 14px 18px;
  color: #ffffff;
  background: var(--primary);
  border: 1px solid var(--primary);
}

.btn-primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.btn-primary:active {
  background: var(--primary-pressed);
  border-color: var(--primary-pressed);
  transform: translateY(1px);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin: 0;
  min-height: 1.5em;
  color: var(--muted);
  font-size: 0.95rem;
  text-align: center;
}

@media (max-width: 420px) {
  .card {
    padding: 20px 16px;
    gap: 18px;
  }

  .swatch {
    gap: 10px;
    padding: 8px;
  }

  .swatch-color {
    flex-basis: 52px;
    width: 52px;
    height: 52px;
  }

  .lock-btn {
    min-width: 72px;
    padding: 9px 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

(function () {
  "use strict";

  var SWATCH_COUNT = 5;
  var swatchesEl = document.getElementById("swatches");
  var generateBtn = document.getElementById("generate");
  var statusEl = document.getElementById("status");

  var state = [];

  function randomInt(max) {
    return Math.floor(Math.random() * max);
  }

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;

    if (h < 60) { r = c; g = x; }
    else if (h < 120) { r = x; g = c; }
    else if (h < 180) { g = c; b = x; }
    else if (h < 240) { g = x; b = c; }
    else if (h < 300) { r = x; b = c; }
    else { r = c; b = x; }

    function toHex(v) {
      var n = Math.round((v + m) * 255);
      var str = n.toString(16);
      return str.length === 1 ? "0" + str : str;
    }

    return "#" + toHex(r) + toHex(g) + toHex(b);
  }

  function generateHarmoniousColors() {
    var baseHue = randomInt(360);
    var scheme = randomInt(3);
    var hues = [];
    var i;

    if (scheme === 0) {
      // Analogous
      for (i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + i * 18) % 360);
      }
    } else if (scheme === 1) {
      // Complementary split
      var complement = (baseHue + 180) % 360;
      hues = [baseHue, (baseHue + 30) % 360, complement, (complement + 30) % 360, (complement + 330) % 360];
    } else {
      // Triadic
      hues = [
        baseHue,
        (baseHue + 120) % 360,
        (baseHue + 240) % 360,
        (baseHue + 60) % 360,
        (baseHue + 300) % 360
      ];
    }

    var colors = [];
    for (i = 0; i < SWATCH_COUNT; i++) {
      var sat = 55 + randomInt(30);
      var light = 42 + randomInt(26);
      colors.push(hslToHex(hues[i], sat, light));
    }
    return colors;
  }

  function createSwatchElement(index) {
    var row = document.createElement("div");
    row.className = "swatch";
    row.dataset.index = String(index);

    var color = document.createElement("div");
    color.className = "swatch-color";
    color.setAttribute("aria-hidden", "true");

    var info = document.createElement("div");
    info.className = "swatch-info";

    var hex = document.createElement("span");
    hex.className = "swatch-hex";

    var label = document.createElement("span");
    label.className = "swatch-label";
    label.textContent = "Color " + (index + 1);

    info.appendChild(hex);
    info.appendChild(label);

    var lock = document.createElement("button");
    lock.type = "button";
    lock.className = "lock-btn";
    lock.dataset.index = String(index);
    lock.setAttribute("aria-pressed", "false");
    lock.setAttribute("aria-label", "Lock color " + (index + 1));
    lock.textContent = "Lock";

    lock.addEventListener("click", function () {
      toggleLock(index);
    });

    row.appendChild(color);
    row.appendChild(info);
    row.appendChild(lock);

    return { row: row, color: color, hex: hex, lock: lock };
  }

  var elements = [];

  function buildSwatches() {
    for (var i = 0; i < SWATCH_COUNT; i++) {
      var parts = createSwatchElement(i);
      elements.push(parts);
      swatchesEl.appendChild(parts.row);
    }
  }

  function render() {
    for (var i = 0; i < SWATCH_COUNT; i++) {
      var item = state[i];
      var el = elements[i];
      el.color.style.backgroundColor = item.hex;
      el.hex.textContent = item.hex.toUpperCase();
      el.lock.setAttribute("aria-pressed", item.locked ? "true" : "false");
      el.lock.setAttribute("aria-label", (item.locked ? "Unlock" : "Lock") + " color " + (i + 1));
      el.lock.textContent = item.locked ? "Locked" : "Lock";
      el.row.classList.toggle("is-locked", item.locked);
    }
  }

  function toggleLock(index) {
    state[index].locked = !state[index].locked;
    render();
    statusEl.textContent = "Color " + (index + 1) + (state[index].locked ? " locked." : " unlocked.");
  }

  function generate() {
    var fresh = generateHarmoniousColors();
    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (!state[i].locked) {
        state[i].hex = fresh[i];
      }
    }
    render();
    statusEl.textContent = "New palette generated.";
  }

  function init() {
    var initial = generateHarmoniousColors();
    for (var i = 0; i < SWATCH_COUNT; i++) {
      state.push({ hex: initial[i], locked: false });
    }
    buildSwatches();
    render();

    generateBtn.addEventListener("click", generate);
  }

  init();
})();
